import React, { useEffect, useState } from "react";
import axios from "axios";

const CompletedTasksPage = () => {
  const [completedTasks, setCompletedTasks] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios
      .get("http://localhost:8000/api/tasks/completed")
      .then((response) => {
        setCompletedTasks(response.data.completed_tasks);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error fetching completed tasks:", error);
        setLoading(false);
      });
  }, []);

  return (
    <div className="max-w-6xl mx-auto py-8 px-4">
      <h1 className="text-3xl font-bold mb-6 text-gray-800">
        Completed Tasks (Approved / Rejected)
      </h1>

      {loading ? (
        <div className="text-center mt-12">
          <div className="text-gray-500">Loading...</div>
        </div>
      ) : completedTasks.length === 0 ? (
        <p className="text-gray-600">No completed tasks found.</p>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {completedTasks.map((task) => (
            <div
              key={`${task.task_id}-${task.approver_email}`}
              className="bg-white p-4 rounded-lg shadow border"
            >
              <h2 className="text-lg font-semibold text-gray-800 mb-1">
                Task #{task.task_id}
              </h2>
              <p className="text-gray-700 mb-2">{task.task_description}</p>
              <p className="text-sm text-gray-500 mb-1">
                Approver: {task.approver_email}
              </p>
              <p
                className={`text-sm font-semibold ${
                  task.approver_status === "Approved"
                    ? "text-green-600"
                    : "text-red-600"
                }`}
              >
                Status: {task.approver_status}
              </p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default CompletedTasksPage;
